update survey_risk_case_info s
left join
(			select a.survey_info_id from (
                select d.survey_info_id,d.investigator_re_id from investigator_re_details d
            ) a left join investigator_re_details d on a.survey_info_id = d.survey_info_id
            left join investigator_re_info r on a.investigator_re_id = r.id
            where r.re_id = #{reId,jdbcType=BIGINT}
            group by a.survey_info_id having max(r.re_state) = min(r.re_state) and max(r.re_state) = 6
) t on s.id = t.survey_info_id
set s.reim_state = 2 where t.survey_info_id is not null
